import { existsSync } from 'node:fs'
import { defineConfig } from 'prisma/config'

// La CLI Prisma ne lit pas .env d'elle-même.
if (existsSync('.env')) process.loadEnvFile('.env')

export default defineConfig({
  schema: 'prisma/schema.prisma',
  datasource: {
    // Optionnelle ici : `prisma generate` (postinstall, CI) tourne sans base.
    url: process.env.DATABASE_URL,
  },
})

// Aucun modèle pour l'instant : le premier arrivera avec la feature d'authentification.
generator client {
  provider = "prisma-client"
  output   = "../src/repositories/generated/prisma"
}

datasource db {
  provider = "postgresql"
}

import type { CorsOptions } from 'cors'

// 3000 : port de dev de portfolio-frontend. 5173 à 5176 : ports Vite par défaut.
const ALLOWED_ORIGINS = [
  'http://localhost:3000',
  'http://localhost:5173',
  'http://localhost:5174',
  'http://localhost:5175',
  'http://localhost:5176',
]

export const corsOptions: CorsOptions = {
  origin: ALLOWED_ORIGINS,
}

import { readFileSync } from 'node:fs'

const packageJson = JSON.parse(readFileSync(new URL('../../package.json', import.meta.url), 'utf8')) as {
  name: string
  version: string
}

const databaseUrl = process.env.DATABASE_URL
if (!databaseUrl) {
  throw new Error('DATABASE_URL manquante : copier .env.example vers .env et y coller la chaîne Neon.')
}

export const env = {
  port: Number(process.env.PORT ?? 4000),
  databaseUrl,
  serviceName: packageJson.name,
  serviceVersion: packageJson.version,
}

import type { Request, Response } from 'express'
import { checkDatabase, getProcessHealth } from '@/services/health/healthService.js'
import { healthRepository } from '@/repositories/healthRepository.js'

export function getHealth(_req: Request, res: Response) {
  res.json(getProcessHealth())
}

export async function getDbHealth(_req: Request, res: Response) {
  const dbHealth = await checkDatabase(healthRepository)
  res.status(dbHealth.status === 'up' ? 200 : 503).json(dbHealth)
}

import type { Request, Response } from 'express'
import { env } from '@/config/env.js'
import { describeService } from '@/services/root/rootService.js'

export function getRoot(_req: Request, res: Response) {
  res.json(describeService(env.serviceName, env.serviceVersion))
}

import { app } from '@/app.js'
import { env } from '@/config/env.js'

app.listen(env.port, () => {
  console.log(`${env.serviceName} écoute sur http://localhost:${env.port}`)
})

import type { NextFunction, Request, Response } from 'express'

// Express ne reconnaît un middleware d'erreur qu'à ses 4 paramètres.
export function errorHandler(err: unknown, _req: Request, res: Response, _next: NextFunction) {
  console.error(err)
  res.status(500).json({ error: 'Internal Server Error' })
}

import type { Request, Response } from 'express'

export function notFound(req: Request, res: Response) {
  res.status(404).json({ error: 'Not Found', path: req.originalUrl })
}

import type { HealthRepository } from '@/services/health/healthService.js'
import { prisma } from '@/repositories/prismaClient.js'

export const healthRepository: HealthRepository = {
  async ping() {
    await prisma.$queryRaw`SELECT 1`
  },
}

import { PrismaPg } from '@prisma/adapter-pg'
import { PrismaClient } from '@/repositories/generated/prisma/client.js'
import { env } from '@/config/env.js'

export const prisma = new PrismaClient({
  adapter: new PrismaPg({ connectionString: env.databaseUrl, connectionTimeoutMillis: 5000 }),
})

export interface HealthRepository {
  ping: () => Promise<void>
}

export function getProcessHealth() {
  return {
    status: 'ok',
    uptime: process.uptime(),
    timestamp: new Date().toISOString(),
  }
}

export async function checkDatabase(repository: HealthRepository) {
  const start = performance.now()
  try {
    await repository.ping()
    return { status: 'up' as const, latencyMs: Math.round(performance.now() - start) }
  } catch {
    return { status: 'down' as const }
  }
}

// À tenir à jour à chaque route ajoutée : cette liste sert de doc d'entrée en attendant la vraie.
const ENDPOINTS = [
  { method: 'GET', path: '/', description: "Nom, version et endpoints de l'API" },
  { method: 'GET', path: '/health', description: 'État du process' },
  { method: 'GET', path: '/db-health', description: 'Disponibilité et latence de la base de données' },
]

export function describeService(name: string, version: string) {
  return { name, version, endpoints: ENDPOINTS }
}
